const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});

// Propagar el campo "expediente" (texto del formulario web) a todos los items hijos
const expedienteForm = item.json.expediente || item.json.body?.expediente || '';

const items = binaryKeys.map(key => ({
  json: {
    filename: item.binary[key].fileName,
    expedienteForm: expedienteForm
  },
  binary: { data: item.binary[key] }
}));

return items;

const item = $input.first();
const fileName = item.binary?.data?.fileName || '';
const mimeType = item.binary?.data?.mimeType || '';

const esImagen = mimeType.includes('image') || 
                 fileName.match(/\.(jpg|jpeg|png|tiff|tif|bmp)$/i);

return [{
  json: {
    ...item.json,
    necesitaOCR: !!esImagen,
    fileName,
    mimeType
  },
