const item = $input.first();

if (item.json.candidates) {
  const texto = item.json.candidates
    .map(c => (c.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join('') || '')
    .join('\n\n');
  return [{ json: { text: texto, source: 'gemini_ocr' } }];
}

if (item.json.text) {
  return [{ json: { text: item.json.text, source: 'digital' } }];
}

return [{ json: { text: '', source: 'unknown' } }];

