const docId = $('Code in JavaScript3').first().json.docId;
const nombreArchivo = $('Code in JavaScript3').first().json.nombreArchivo;

return [{
  json: {
    docId: docId,
    nombreArchivo: nombreArchivo
  }
}];

const item = $input.first();
const filename = (item.json.filename || '').toLowerCase();

const extensionesPermitidas = ['.pdf', '.jpg', '.jpeg', '.png', '.tiff', '.tif'];
const esValido = extensionesPermitidas.some(ext => filename.endsWith(ext));

if (!esValido) {
  const extension = filename.includes('.')
    ? filename.split('.').pop().toUpperCase()
    : 'desconocido';

  // Marcamos el item como inválido pero lo dejamos pasar
  // para que el pipeline llegue hasta respondToWebhook
  return [{
    json: {
      ...item.json,
      archivoInvalido: true,
      mensajeError: `El archivo "${item.json.filename}" tiene formato .${extension} que no es compatible. Por favor convertilo a PDF antes de enviarlo.`
    },
    binary: item.binary
  }];
}

return [{ json: { ...item.json, archivoInvalido: false }, binary: item.binary }];

// Arma el pedido del validador para el sub-workflow "Gemini con rotación de claves (Hark)" (kYDhcme8j6T8BZ7O).
// Prompt idéntico al del nodo HTTP anterior (gemini-2.5-flash). Clave C (Iname) primero; A/B de respaldo.
// Sin maxOutputTokens: Gemini 3.x usa su máximo por defecto, no se corta.
const body = {
  contents: [
    {
      parts: [
        {
          text: "Eres un evaluador regulatorio de ANMAT/INAME especializado en modificaciones post-registro de productos biológicos. Analiza el siguiente conjunto de documentos presentados por un laboratorio y evalúa si la solicitud cumple los requisitos formales MÍNIMOS.\\n\\nDOCUMENTOS RECIBIDOS:\\n" + $('Obtener todos los textos').first().json.data.map(d => d.text).join('\\n\\n---\\n\\n') + "\\n\\nRealiza tu evaluación siguiendo EXACTAMENTE estos 4 pasos:\\n\\nPASO 1: Identificación del expediente y producto\\nExtrae los datos del Formulario de Solicitud (si falta, de la Nota de Presentación). El número de expediente sale SOLO del campo Número de Expediente ANMAT del Formulario; si no figura ahí, escribe NO IDENTIFICADO (no uses el Número de Registro). Formatea así exactamente:\\n- EXPEDIENTE: [valor o NO IDENTIFICADO]\\n- PRODUCTO: [nombre comercial o NO IDENTIFICADO]\\n- EMPRESA: [valor literal del campo Razón Social del Formulario o Titular del Registro de la Nota, hasta el tipo societario S.A./S.R.L. inclusive]\\n- IFA: [valor o NO IDENTIFICADO]\\n\\nPASO 2: Verificación de motivo y tipo de trámite\\nIndica cuál es el motivo de la modificación solicitada y a qué tipo de trámite corresponde.\\n\\nPASO 3: Verificación de documentos mínimos obligatorios\\nResponde con SI o NO a cada uno de los siguientes puntos:\\n- ¿Se recibió al menos una Nota de Presentación o documento similar? SI/NO\\n- ¿Se recibió un Formulario de Solicitud o documento con datos del expediente? SI/NO\\n- ¿Se recibió el Documento declarado por el regulado (validación del método analítico, CTD 3.2.S.4.3)? SI/NO\\n- ¿El motivo de la Nota, la descripción del cambio del Formulario y el alcance del Documento declarado contienen información regulatoria real (no textos ajenos como poemas, canciones o recetas)? SI/NO\\n- ¿Los datos básicos (producto, empresa) son coherentes entre los documentos recibidos? SI/NO\\nIMPORTANTE: El número de expediente ANMAT y el número de registro del producto son campos DISTINTOS, no los compares entre sí.\\nIMPORTANTE: NO evalúes si faltan módulos CTD adicionales. Solo evalúa los 3 documentos mínimos: Nota de Presentación, Formulario de Solicitud y Documento declarado por el regulado.\\n\\nPASO 4: Recomendación final\\nSi TODOS los puntos del PASO 3 son SI, recomienda VALIDAR. Si alguno es NO, recomienda OBJETAR.\\n\\nCONCLUSIÓN:\\nResume en un párrafo breve (máximo 3 líneas) el resultado de tu evaluación."
        }
      ]
    }
  ]
};
return [{ json: { body, gemini: { check: 'text', prefer_key: 'C', purpose: 'ctd-validador' } } }];

// Arma el pedido de OCR para el sub-workflow "Gemini con rotación de claves (Hark)" (kYDhcme8j6T8BZ7O).
// Antes el nodo HTTP mandaba el cuerpo vacío (sin la imagen). Ahora va la imagen inline + instrucción de transcripción.
// Clave C (Iname) primero; A/B de respaldo. Gemini acepta PNG/JPEG/WEBP/HEIC (no TIFF/BMP).
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const it = $input.all()[i];
  const bin = (it.binary || {}).data || {};
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let mime = bin.mimeType || 'image/jpeg';
  if (mime === 'image/jpg') mime = 'image/jpeg';
  out.push({ json: {
    body: { contents: [{ role: 'user', parts: [
      { text: 'Transcribí textualmente TODO el texto visible de este documento escaneado, en su idioma original, respetando el orden, tablas y saltos de línea. Devolvé solo el texto transcripto, sin comentarios ni resumen.' },
      { inline_data: { mime_type: mime, data: buf.toString('base64') } },
    ] }] },
    gemini: { check: 'text', prefer_key: 'C', purpose: 'ctd-ocr' },
    fileName: it.json.fileName || it.json.filename || '',
  } });
}
return out;
